/*
 Problem: 1301. Number of Paths with Max Score
 Language: cpp
 Runtime: 7 ms (79.59%)
 Memory: 11.6 MB (91.68%)
 Tags: Array, Dynamic Programming, Matrix
*/
class Solution {
public:
    vector<int> pathsWithMaxScore(vector<string>& board) {
        static constexpr int MOD = 1e9 + 7;
        static constexpr array<pair<int, int>, 3> DIR{{
            {-1, 0},
            {0, -1},
            {-1, -1}
        }};

        const int n = board.size();

        vector<vector<int>> dp(n, vector<int>(n, -1));
        vector<vector<int>> cnt(n, vector<int>(n));

        dp[0][0] = 0;
        cnt[0][0] = 1;

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (!i && !j || board[i][j] == 'X') {
                    continue;
                }

                int best = -1;
                int ways = 0;

                for (const auto& [dx, dy] : DIR) {
                    const int x = i + dx;
                    const int y = j + dy;

                    if (x < 0 || y < 0 || dp[x][y] == -1) {
                        continue;
                    }

                    if (dp[x][y] > best) {
                        best = dp[x][y];
                        ways = cnt[x][y];
                    } else if (dp[x][y] == best) {
                        ways = (ways + cnt[x][y]) % MOD;
                    }
                }

                if (best == -1) {
                    continue;
                }

                dp[i][j] = best;
                cnt[i][j] = ways;

                if (isdigit(board[i][j])) {
                    dp[i][j] += board[i][j] - '0';
                }
            }
        }

        if (dp[n - 1][n - 1] == -1) {
            return {0, 0};
        }

        return {dp[n - 1][n - 1], cnt[n - 1][n - 1]};
    }
};
